parameters.jsCode:
let raw = $input.first().json.candidates[0].content.parts[0].text.trim();

// Extract DATABASE marker
let db = '';
const dbMatch = raw.match(/DATABASE:\s*(employee_db|org_db)/i);
if (dbMatch) {
  db = dbMatch[1].toLowerCase();
}

// Clean raw code fences
let cleanedRaw = raw.replace(/```sql/gi, '').replace(/```/g, '').trim();

// Extract SELECT statement
let sql = '';
let sqlMatch = cleanedRaw.match(/(SELECT[\s\S]+?)(;|$)/i);
if (sqlMatch) {
  sql = sqlMatch[1].trim();
} else {
  sql = cleanedRaw;
}

// Fallback database selection if marker not found
if (!db) {
  if (/schools/i.test(sql)) {
    db = 'org_db';
  } else if (/employees/i.test(sql)) {
    db = 'employee_db';
  } else {
    db = 'employee_db';
  }
}

// SAFETY
const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|EXECUTE)\b/i;
if (forbidden.test(sql)) { throw new Error('Unsafe SQL blocked: ' + sql); }
if (!/^\s*SELECT/i.test(sql)) { throw new Error('Only SELECT allowed: ' + sql); }
if (!/LIMIT/i.test(sql) && !/COUNT|SUM|AVG|MIN|MAX|GROUP BY/i.test(sql)) {
  sql = sql.replace(/;?\s*$/, '') + ' LIMIT 1000';
}

return [{ json: { db: db, sql: sql, question: $('Build Prompt').first().json.question } }];

